<?php
declare(strict_types=1);
require __DIR__ . '/bootstrap.php';
header('Content-Type: application/json; charset=utf-8'); apiRequirePost(); apiRequireAdmin(); $input = apiInput();
$slug = strtolower(preg_replace('/[^a-z0-9-]+/', '-', apiText($input, 'slug', 140)) ?? ''); $title = apiText($input, 'title', 180); $excerpt = apiText($input, 'excerpt', 320); $content = apiText($input, 'content', 30000); $status = apiText($input, 'status', 16); $publishedAt = apiText($input, 'publishedAt', 30);
if ($slug === '' || $title === '' || $content === '' || !in_array($status, ['draft', 'scheduled', 'published', 'archived'], true)) apiRespond(422, ['ok' => false, 'message' => 'Datos de publicación inválidos.']);
try { $statement = apiPdo()->prepare("INSERT INTO posts (slug, title, excerpt, content, seo_title, seo_description, featured_image, featured_image_alt, status, is_active, published_at, created_at, updated_at) VALUES (:slug,:title,:excerpt,:content,:seoTitle,:seoDescription,:image,:imageAlt,:status,:active,:publishedAt,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE title=VALUES(title), excerpt=VALUES(excerpt), content=VALUES(content), seo_title=VALUES(seo_title), seo_description=VALUES(seo_description), featured_image=VALUES(featured_image), featured_image_alt=VALUES(featured_image_alt), status=VALUES(status), is_active=VALUES(is_active), published_at=VALUES(published_at), updated_at=UTC_TIMESTAMP()"); $statement->execute([':slug'=>$slug, ':title'=>$title, ':excerpt'=>$excerpt, ':content'=>$content, ':seoTitle'=>apiText($input,'seoTitle',180), ':seoDescription'=>apiText($input,'seoDescription',320), ':image'=>apiText($input,'featuredImage',255), ':imageAlt'=>apiText($input,'featuredImageAlt',180), ':status'=>$status, ':active'=>(bool)($input['isActive'] ?? true), ':publishedAt'=>$publishedAt ?: null]); apiRespond(200, ['ok'=>true, 'slug'=>$slug]); } catch (Throwable $error) { error_log('FaruTech post management: '.$error->getMessage()); apiRespond(500, ['ok'=>false, 'message'=>'No fue posible guardar la publicación.']); }
